  let featherFactor = getFeatherFactor(uv);
  let finalAlpha = params.opacity * (1.0 - featherFactor);
  
  let blendedColor = mix(color, processedColor, finalAlpha);
  
  textureStore(outputTexture, global_id.xy, blendedColor);
